import { chromium } from 'playwright-core';
import assert from 'node:assert/strict';
import { mkdir } from 'node:fs/promises';
const browser = await chromium.launch({ executablePath: process.env.CHROME_PATH ?? '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true });
try {
 await mkdir('/tmp/malink-simple-flow-qa', {recursive:true});
 for (const width of [390,1280]) {
  const page = await browser.newPage({viewport:{width,height:844}});
  const errors=[]; page.on('pageerror', e=>errors.push(e.message));
  await page.goto(process.env.SETTINGS_FIXTURE_URL ?? 'http://127.0.0.1:4182/malink/tests/fixtures/computer-settings/');
  await page.getByRole('button',{name:'Refresh status for Tokyo server · Tokyo',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.liveChecked),'tokyo');
  assert.equal(await page.getByRole('region',{name:'Gateway management',exact:true}).count(),0);
  await page.screenshot({path:'/tmp/malink-simple-flow-qa/cards-'+width+'.png'});
  await page.getByRole('button',{name:'Manage Tokyo server · Tokyo',exact:true}).click();
  const management=()=>page.getByRole('region',{name:'Gateway management',exact:true});
  const panel=()=>page.locator('.computer-action-dialog').last();
  assert.equal(await page.getByRole('button',{name:/^Manage computer|^Versions|^Update activity/}).count(),0);
  await management().getByRole('button',{name:'Update',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.updatedNode),'tokyo');
  await management().getByRole('button',{name:'Open update session',exact:true}).click();
  await page.getByRole('heading',{name:'Update session'}).waitFor();
  await page.getByRole('button',{name:'Back to computer settings'}).click();
  await page.evaluate(()=>window.setFixturePhase('staged'));
  await management().getByRole('button',{name:'Restart and install update',exact:true}).click();
  await panel().getByRole('button',{name:'Confirm',exact:true}).click();
  await management().getByRole('heading',{name:'Update complete',exact:true}).waitFor();
  await page.screenshot({path:'/tmp/malink-simple-flow-qa/complete-'+width+'.png'});
  await management().getByRole('button',{name:'Delete update session',exact:true}).click();
  await panel().getByRole('button',{name:'Confirm',exact:true}).click();
  await management().getByRole('button',{name:'Deleting…',exact:true}).waitFor();
  assert.equal(await management().getByRole('button',{name:'Open update session',exact:true}).count(),1);
  await page.evaluate(()=>window.finishDelete());
  assert.equal(await management().getByRole('button',{name:'Open update session',exact:true}).count(),0);
  await management().getByRole('button',{name:'Temporarily use previous version',exact:true}).click();
  await panel().getByText(/This is temporary recovery/).waitFor();
  await panel().getByRole('button',{name:'Confirm',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.selectedVersion),'v1');
  await management().getByRole('button',{name:'Update',exact:true}).waitFor();
  await management().getByText(/Using an older version temporarily/).waitFor();
  await page.screenshot({path:'/tmp/malink-simple-flow-qa/rollback-'+width+'.png'});
  await page.getByRole('button',{name:/^Restart Gateway/}).click();
  await panel().getByRole('button',{name:'Restart when idle',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.restart.mode),'when_idle');
  await page.keyboard.press('Escape');
  assert.deepEqual(await page.evaluate(()=>[...document.querySelectorAll('.computer-details,.matrix-settings-body')].filter(el=>el.scrollWidth>el.clientWidth+2).map(el=>el.className)),[]);
  assert.deepEqual(errors,[]);
  console.log(JSON.stringify({width,errors,refreshSeparated:true,updateLifecycle:true,rollbackUpdatesAgain:true}));
  await page.close();
 }
} finally { await browser.close(); }
